tool.command:
## Check inputs have no duplicated element_identifier: #set labels = [input.element_identifier for input in $infiles] #set duplicates = [label for label in labels if labels.count(label) > 1] #if len(duplicates) > 0: #set unique_duplicates = list(set(duplicates)) echo "Cannot run ilastik because these identifiers are present more than once:" && #for label in $unique_duplicates: echo $label && #end for exit 1 && #end if export HOME=\$PWD && ## NFS root_squash: root in container → nobody on NFS, can't write to galaxy-owned workdir. ## Create a temporary uid=1001 (galaxy_master) user inside the container so NFS writes ## are owned by galaxy_master. USER_ID/GROUP_ID tell jlesage/baseimage-gui /init to run ## the app as uid=1001 as well, matching the EU usegalaxy.eu approach (RFC00165 avoided). groupadd -g 1001 gxgroup 2>/dev/null || true && useradd -M -u 1001 -g 1001 gxuser 2>/dev/null || true && ## Create output dirs as uid=1001 (NFS-safe): #if str($input_type.existing) == "existing": runuser -u gxuser -- bash -c "mkdir -p ./output ./zarr_output && cp '$input_type.project' ./output/MyProject.ilp" && #else: runuser -u gxuser -- bash -c "mkdir -p ./output ./zarr_output" && #end if ## Link input images to current working directory (as uid=1001, NFS-safe). ## runuser direct-binary fails PAM in this container; wrap in bash -c instead. ## Skip adding extension if element_identifier already ends with it (from EU). #for input in $infiles: #if $input.element_identifier.endswith($input.ext): runuser -u gxuser -- bash -c "ln -s '$input' ./'$input.element_identifier'" && #else: runuser -u gxuser -- bash -c "ln -s '$input' './${input.element_identifier}.${input.ext}'" && #end if #end for ## Write the ilastik startup script directly to /bin/ (container-local, root-writable). #if str($input_type.existing) == "new": printf '%s
' 'ilastik --new_project \$HOME/output/MyProject.ilp --workflow $input_type.Workflow' > /bin/ilastik_with_args && chmod +x /bin/ilastik_with_args && #else: printf '%s
' 'ilastik --project \$HOME/output/MyProject.ilp' > /bin/ilastik_with_args && chmod +x /bin/ilastik_with_args && #end if ## /init (jlesage/baseimage-gui) calls mktemp early; Galaxy sets TMPDIR=$CWD/tmp/ which is ## NFS root_squash-protected. Reset to container-local /tmp before /init runs. export TMPDIR=/tmp && ## Reconfigure container nginx to serve noVNC at the Galaxy proxy path prefix. ## /defaults/default_site.conf is copied to /var/tmp/nginx/ by 10-nginx.sh during /init. EP_PATH_CLEAN="\${EP_PATH%/}" && sed -i '/error_page 497/d' /defaults/default_site.conf && sed -i "s|location /websockify {|location \${EP_PATH_CLEAN}/websockify {
 websockify_pass unix:/tmp/vnc.sock;
 websockify_read_timeout 5d;
 websockify_send_timeout 5d;
 }

 location \${EP_PATH_CLEAN} {
 alias /opt/noVNC/;
 index index.html;
 add_header Cache-Control no-cache;
 }

 location /websockify {|" /defaults/default_site.conf && /init && if [ -n "\$(ls -A ./zarr_output 2>/dev/null)" ]; then runuser -u gxuser -- bash -c "mkdir -p '$zarr_output.extra_files_path' && cp -r ./zarr_output/* '$zarr_output.extra_files_path'"; fi
